diff --git a/src/notify.ts b/src/notify.ts
index 3de32af..5dc70c3 100644
--- a/src/notify.ts
+++ b/src/notify.ts
@@ -14,3 +14,28 @@ export interface Outbox {
 export const enqueue = (outbox: Outbox, update: Update): void => {
   outbox.append({ ...update, deliveredAt: null });
 };
+
+export class DurableOutbox implements Outbox {
+  private updates: Map<string, Update> = new Map();
+
+  append(update: Update): void {
+    this.updates.set(update.id, { ...update, deliveredAt: null });
+  }
+
+  pending(): readonly Update[] {
+    return Array.from(this.updates.values()).filter(u => u.deliveredAt === null);
+  }
+
+  markDelivered(id: string, at: number): void {
+    const update = this.updates.get(id);
+    if (update) {
+      this.updates.set(id, { ...update, deliveredAt: at });
+    }
+  }
+
+  restore(stored: Update[]): void {
+    for (const update of stored) {
+      this.updates.set(update.id, update);
+    }
+  }
+}
